#include "Code/Sparkplug/spContactMultirowQueries.h"
#include "Analysis/PC/spContactMultirowAbi.h"
#include <algorithm>
#include <array>
#include <cstdint>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <utility>
namespace
{
    using namespace sparkplug::reconstruction;
    using State=spContactMultirowStateForAnalysis;
    using Input=spContactMultirowInputForAnalysis;
    using Result=spContactMultirowResultForAnalysis;
    constexpr auto Qualified=spContactMultirowProfileForAnalysis::PcCapturedWarmFiniteNearest037F;
    static_assert(sizeof(State)==384);
    unsigned checks=0;
    void Check(const bool ok){++checks;if(!ok)throw std::runtime_error("Contact Multirow contract failed");}
    unsigned Nibble(const char c)
    {if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;throw std::runtime_error("invalid hex");}
    std::uint32_t Word(const std::uint8_t* p)
    {return std::uint32_t{p[0]}|std::uint32_t{p[1]}<<8|std::uint32_t{p[2]}<<16|std::uint32_t{p[3]}<<24;}
    void Put(State& state,const std::size_t off,const std::uint32_t word)
    {for(unsigned b=0;b!=4;++b)state.contact[off+b]=static_cast<std::uint8_t>(word>>(8*b));}
    State Parse(const std::string& text)
    {
        if(text.size()!=768)throw std::runtime_error("Multirow projection requires384B");
        std::array<std::uint8_t,384> bytes{};
        for(unsigned i=0;i!=384;++i)bytes[i]=static_cast<std::uint8_t>((Nibble(text[i*2])<<4)|Nibble(text[i*2+1]));
        State result;std::copy_n(bytes.begin(),228,result.contact.begin());std::size_t at=228;
        const auto array=[&bytes,&at](auto& out){for(auto& word:out){word=Word(bytes.data()+at);at+=4;}};
        array(result.raw6C);array(result.raw74);array(result.raw78);array(result.raw7C);array(result.raw80);array(result.raw84);return result;
    }
    std::string Hex(const State& state)
    {
        static constexpr char digits[]="0123456789abcdef";std::string text;
        const auto byte=[&text](const std::uint8_t b){text.push_back(digits[b>>4]);text.push_back(digits[b&15]);};
        for(const auto b:state.contact)byte(b);
        const auto array=[&byte](const auto& words){for(const auto word:words)for(unsigned b=0;b!=4;++b)byte(static_cast<std::uint8_t>(word>>(8*b)));};
        array(state.raw6C);array(state.raw74);array(state.raw78);array(state.raw7C);array(state.raw80);array(state.raw84);return text;
    }
    struct Example final{const char* input;const char* expected;};
    // Offline instruction/Fraction predictions only. Native/current-source
    // qualification must be bound separately after actual saved comparisons.
    const Example Examples[]={
        {" 3F800000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 3E800000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 40800000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 40400000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 3F400000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 3FC00000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 3F800000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 3E800000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 40800000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 40400000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 3F400000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 3FC00000 3F800000 40000000 40400000 3E4CCCCD 3727C5AC",""},
        {" 3F800000 00000000 00000000 B3800000 3E4CCCCD 3727C5AC",""},
        {" 3E800000 00000000 00000000 B3800000 3E4CCCCD 3727C5AC",""},
        {" 40800000 00000000 00000000 B3800000 3E4CCCCD 3727C5AC",""},
        {" 40400000 00000000 00000000 B3800000 3E4CCCCD 3727C5AC",""},
    };
    std::pair<State,Input> ReadInput(const std::string& line)
    {
        std::istringstream stream(line);std::string raw;Input input;
        if(!(stream>>raw>>std::hex>>input.scalarArgumentWord>>input.bodyPointWords[0]>>input.bodyPointWords[1]>>input.bodyPointWords[2]>>input.managerRaw7C>>input.managerRaw80))throw std::runtime_error("invalid Multirow input");
        std::string extra;if(stream>>extra)throw std::runtime_error("trailing Multirow input");return {Parse(raw),input};
    }
    std::string Replay(const std::string& line)
    {auto [before,input]=ReadInput(line);State output;if(ComputeContactMultirowForAnalysis(before,input,output,Qualified)!=Result::Completed)throw std::runtime_error("Multirow refusal");return Hex(output);}
    void Unit()
    {
        for(const auto& example:Examples)
        {
            auto [before,input]=ReadInput(example.input);const auto original=Hex(before);
            struct Guarded final{std::array<std::uint8_t,16> left;State value;std::array<std::uint8_t,16> right;};
            Guarded output{};output.left.fill(0xD7);output.right.fill(0xD7);
            Check(ComputeContactMultirowForAnalysis(before,input,output.value,Qualified)==Result::Completed);Check(Hex(output.value)==example.expected);Check(Hex(before)==original);
            Check(std::all_of(output.left.begin(),output.left.end(),[](auto b){return b==0xD7;}));Check(std::all_of(output.right.begin(),output.right.end(),[](auto b){return b==0xD7;}));
            auto alias=before;Check(ComputeContactMultirowForAnalysis(alias,input,alias,Qualified)==Result::Completed);Check(Hex(alias)==example.expected);
            Check(ComputeContactMultirowForAnalysis(alias,input,alias,Qualified)==Result::Completed);Check(Hex(alias)==example.expected);
            const auto count=Word(before.contact.data()+0x58);
            for(unsigned row=1;row!=3;++row)Check(output.value.raw74[row]==before.raw74[row]);
            for(unsigned row=0;row!=3;++row)
            {
                Check(output.value.raw6C[row*8+3]==before.raw6C[row*8+3]);Check(output.value.raw6C[row*8+7]==before.raw6C[row*8+7]);
                if(row>=count)for(unsigned lane=0;lane!=8;++lane)Check(output.value.raw6C[row*8+lane]==before.raw6C[row*8+lane]);
            }
        }
        auto [before,input]=ReadInput(Examples[0].input);State output=before;const auto unchanged=Hex(output);
        Check(ComputeContactMultirowForAnalysis(before,input,output)==Result::UnqualifiedProfile);Check(Hex(output)==unchanged);
        const auto refused=[&](const State& state,const Input value,const Result result){Check(ComputeContactMultirowForAnalysis(state,value,output,Qualified)==result);Check(Hex(output)==unchanged);};
        auto changed=before;Put(changed,0,0);refused(changed,input,Result::CapturedPrimaryNotAdmitted);
        for(const auto off:{0x40U,0x4CU,0x70U,0x88U})for(const auto word:{1U,0x100U,0x80000000U}){changed=before;Put(changed,off,word);refused(changed,input,Result::FixedStateNotAdmitted);}
        for(const auto count:{0U,1U,4U,0xFFFFFFFFU}){changed=before;Put(changed,0x58,count);refused(changed,input,Result::FixedStateNotAdmitted);}
        for(const auto off:{0x48U,0x6CU,0x74U,0x78U,0x7CU,0x80U,0x84U}){changed=before;Put(changed,off,0);refused(changed,input,Result::FixedStateNotAdmitted);}
        auto bad=input;bad.managerRaw7C^=1;refused(before,bad,Result::ManagerProfileNotAdmitted);bad=input;bad.managerRaw80^=1;refused(before,bad,Result::ManagerProfileNotAdmitted);
        for(const auto word:{0U,0x80000000U,0xBF800000U,0x3E7FFFFFU,0x40800001U,0x7F800000U,0x7FC00001U}){bad=input;bad.scalarArgumentWord=word;refused(before,bad,Result::OutOfDomain);}
        for(const auto off:{0xB4U,0xB8U,0xBCU,0xC0U,0xC4U,0xC8U,0xCCU,0x8CU})for(const auto word:{0x41800001U,0xC1800001U,0x7FC00001U,0x7F800000U}){changed=before;Put(changed,off,word);refused(changed,input,Result::OutOfDomain);}
        for(unsigned lane=0;lane!=3;++lane){bad=input;bad.bodyPointWords[lane]=0x7FC00001U;refused(before,bad,Result::OutOfDomain);}
        for(const auto sign:{0U,0x80000000U}){changed=before;Put(changed,0xC0,sign);Put(changed,0xC4,0);Put(changed,0xC8,0xBF800000U);refused(changed,input,Result::OutOfDomain);}
        // raw90 is outside this operation's selected numeric domain.
        changed=before;Put(changed,0x90,0x7FC00123U);State result;Check(ComputeContactMultirowForAnalysis(changed,input,result,Qualified)==Result::Completed);Check(Word(result.contact.data()+0x90)==0x7FC00123U);
        for(const auto word:{0U,0x80000000U,1U,0x80000001U,0xBF800000U})
        {changed=before;Put(changed,0x8C,word);Check(ComputeContactMultirowForAnalysis(changed,input,result,Qualified)==Result::Completed);for(unsigned row=1;row!=3;++row){Check(result.raw7C[row]==(word^0x80000000U));Check(result.raw80[row]==word);}}
        std::cout<<"ContactMultirow: "<<checks<<" contracts passed\n";
    }
}
int main(const int argc,char** argv)
{
    try{if(argc==2&&std::string(argv[1])=="--replay"){std::string line;while(std::getline(std::cin,line))if(!line.empty())std::cout<<Replay(line)<<'\n';}else Unit();return 0;}
    catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}
}
